-- State transitions declared for UserPermission (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION user_permissions_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('active', 'inactive'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: user_permissions.status % -> %', OLD."status", NEW."status";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS user_permissions_status_transition_check ON user_permissions;
CREATE TRIGGER user_permissions_status_transition_check
    BEFORE UPDATE OF "status" ON user_permissions
    FOR EACH ROW EXECUTE FUNCTION user_permissions_status_transition_check();
